<?php
declare(strict_types=1);require __DIR__.'/_auth.php';$actor=$auth->requireLogin();$auth->requireRole('ADMIN');$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$user=$id?$auth->users()->find($id):null;if(!$user){http_response_code(404);exit('User not found');}$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$password=(string)($_POST['temporary_password']??'');if(strlen($password)<12)$errors[]='Temporary password must be at least 12 characters.';if(!$errors){$auth->users()->password($id,$password,true);$auth->audit()->log('USER_PASSWORD_RESET',$actor['id'],$actor['username'],'USER',$id);$_SESSION['flash']='Temporary password set.';redirect('users.php');}}$title='Reset Password';$activePage='users';require __DIR__.'/partials/header.php';?>
<?php foreach($errors as $error):?><div class="alert error"><?=e($error)?></div><?php endforeach;?><form method="post" class="panel form-section"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$id?>"><div class="panel-head"><div><h2>Reset <?=e($user['username'])?></h2><p>Set a temporary password. The user must replace it after login.</p></div></div><div class="form-grid"><label class="full">Temporary Password<input type="password" name="temporary_password" minlength="12" required autocomplete="new-password"></label></div><div class="form-actions form-pad"><a class="btn secondary" href="users.php">Cancel</a><button class="btn primary">Reset Password</button></div></form><?php require __DIR__.'/partials/footer.php';?>
